mapper.select:
SELECT EXISTS (SELECT 1 FROM code_sessions
WHERE organization_uuid = #{organizationUUID} AND workspace_uuid = #{workspaceUUID} AND session_uuid = #{sessionUUID}
AND metadata #>> '{config,worker_protocol}' = 'dsr1')

mapper.update:
UPDATE dsh_permission_requests SET state = 'closed', resolved_at = NOW()
WHERE  AND state = 'pending'
AND input_id = #{inputID}
AND session_thread_id = #{threadID}

UPDATE dsh_input_executions SET cancel_requested_at = COALESCE(cancel_requested_at, NOW())
WHERE  AND input_id = (
    SELECT input_id FROM dsh_input_executions WHERE  AND status IN ('accepted','running')
    AND session_thread_id = #{threadID}
    ORDER BY CASE WHEN status = 'running' THEN 0 ELSE 1 END, accepted_at, input_id LIMIT 1
)
